import AppKit
import Foundation
import os
import ScriptingBridge

// Selector names below are taken verbatim from the header generated by
//   sdef /Applications/Spotify.app | sdp -fh --basename Spotify
// rather than guessed. Only the members actually used are declared.

@objc private protocol SpotifyTrackScripting {
    var name: String? { get }
    var artist: String? { get }
    var album: String? { get }
    var duration: Int { get }
    var artworkUrl: String? { get }
    var spotifyUrl: String? { get }
}

@objc private protocol SpotifyApplicationScripting {
    var currentTrack: SpotifyTrackScripting? { get }
    var soundVolume: Int { get set }
    var playerState: UInt32 { get }
    var playerPosition: Double { get set }
    var repeating: Bool { get set }
    var shuffling: Bool { get set }
    func nextTrack()
    func previousTrack()
    func playpause()
    func pause()
    func play()
}

/// Drives Spotify.app locally over Apple Events.
///
/// Chosen over the Spotify Web API for control because it needs no Premium subscription, no
/// network round trip and no OAuth, and because it always targets *this* Mac rather than
/// whichever Connect device happens to be active.
final class SpotifyProvider: MediaProvider {
    static let bundleIdentifier = "com.spotify.client"

    let id = ProviderID.spotify
    let displayName = "Spotify"

    /// No `.nativeMute`: Spotify's dictionary has no mute property at all, so mute is
    /// emulated by saving and restoring the volume.
    ///
    /// `.favorite` appears only once the user has signed in to the Web API, because `starred`
    /// is not merely read-only over Apple Events — it is broken in shipping builds (see
    /// `snapshot()`). Declaring it conditionally is what keeps the heart button out of the UI
    /// until it can actually work.
    var capabilities: ProviderCapabilities {
        var caps: ProviderCapabilities = [.seek, .volume, .shuffle, .repeatMode]
        // Both extras ride on the Web API sign-in: `starred` is broken over Apple Events, and
        // `repeating` is a boolean there, so neither the heart nor the third repeat position
        // can work without it.
        if auth?.isConnectedNonisolated == true { caps.formUnion([.favorite, .repeatOne]) }
        return caps
    }

    private static let log = Logger(subsystem: "app.nocta.Nocta", category: "spotify")

    /// Optional. Playback control never needs this; only the Web API extras do.
    private let auth: SpotifyAuth?
    private var web: SpotifyWebClient? { auth.map { SpotifyWebClient(auth: $0) } }

    /// Liked state is cached per track rather than re-read on every poll.
    ///
    /// `snapshot()` runs once a second while anything of ours is on screen. Asking
    /// `/me/tracks/contains` at that rate earns a `429` within about a minute, and because the
    /// lookup degrades to "unknown", a rate-limited read reads back to the UI as *not liked* —
    /// the heart turns itself off. One request per track per minute is enough: the only things
    /// that change the answer are our own `setFavorite` (which writes the result straight into
    /// this cache) and the user liking the track in Spotify itself.
    private let liked = LikedTrackCache()

    /// How long a cached answer is trusted before it is re-read. Long enough to stay well
    /// inside Spotify's rate limit, short enough that a like made in Spotify.app shows up.
    private static let likedRefreshInterval: TimeInterval = 60

    /// Repeat state is global rather than per track, and the user can change it in Spotify's
    /// own window, so it is re-read more often than liked state. Our own writes are recorded
    /// immediately, so this interval only bounds how stale an *external* change can look.
    private static let repeatRefreshInterval: TimeInterval = 15
    private let repeatCache = RepeatStateCache()

    /// Collapses concurrent lookups of the same track onto a single request.
    private let lookups = LikedLookupCoalescer()

    init(auth: SpotifyAuth? = nil) {
        self.auth = auth
    }

    private let client = ScriptingBridgeClient(
        bundleIdentifier: SpotifyProvider.bundleIdentifier,
        appName: "Spotify"
    )

    /// Volume to restore when unmuting, since Spotify cannot mute itself.
    private var volumeBeforeMute: Int?

    func isRunning() -> Bool { client.isRunning() }

    func snapshot() async throws -> PlayerSnapshot {
        var snapshot = try await appleEventsSnapshot()

        // Enrich with liked state only when signed in. A Web API failure must never break
        // playback state, so it degrades to "unknown" rather than propagating.
        if let web, let uri = snapshot.track?.id, auth?.isConnectedNonisolated == true {
            snapshot.track?.isFavorite = await likedState(for: uri, using: web)
        }
        // Apple Events reported `.all` for any repeat that isn't off. Correct it to the real
        // three-state value when we can; leave the boolean reading in place when we can't.
        if let web, auth?.isConnectedNonisolated == true,
           let mode = await repeatState(using: web) {
            snapshot.repeatMode = mode
        }
        return snapshot
    }

    private func appleEventsSnapshot() async throws -> PlayerSnapshot {
        try await client.run { app in
            let spotify = unsafeBitCast(app, to: SpotifyApplicationScripting.self)

            let rawState = spotify.playerState
            let volume = spotify.soundVolume
            let position = spotify.playerPosition

            var track: Track?
            if let raw = spotify.currentTrack, let name = raw.name, !name.isEmpty {
                var artwork: ArtworkSource?
                if let urlString = raw.artworkUrl, let url = URL(string: urlString) {
                    artwork = .url(url)
                }
                track = Track(
                    id: raw.spotifyUrl ?? name,
                    title: name,
                    artist: raw.artist ?? "",
                    album: raw.album ?? "",
                    duration: Self.normalisedDuration(raw.duration),
                    artwork: artwork,
                    // Verified 2026-08-20 against Spotify's shipping build: reading `starred`
                    // fails with errAEEventFailed (-10000) even from osascript, so the
                    // property is present in the dictionary but no longer implemented.
                    // `nil` means "unknown"; the Web API layer fills this in once signed in.
                    isFavorite: nil
                )
            }

            return PlayerSnapshot(
                track: track,
                status: PlayerStateCode.status(from: rawState),
                position: position,
                volume: volume,
                isMuted: volume == 0,
                isShuffling: spotify.shuffling,
                repeatMode: spotify.repeating ? .all : .off,
                capturedAt: Date()
            )
        }
    }

    /// Spotify's scripting dictionary documents `duration` as seconds, but shipping builds
    /// have historically returned milliseconds. Rather than trust either, normalise: no song
    /// runs for 10,000 seconds (2h46m), so a value that large is certainly milliseconds.
    static func normalisedDuration(_ raw: Int) -> TimeInterval {
        raw > 10_000 ? TimeInterval(raw) / 1000 : TimeInterval(raw)
    }

    /// Requires a signed-in Web API session; the UI hides this control otherwise.
    func setFavorite(_ favorite: Bool) async throws {
        guard let web, auth?.isConnectedNonisolated == true else {
            throw ProviderError.unsupported("Liking a Spotify track")
        }
        guard let uri = try await appleEventsSnapshot().track?.id else { return }
        do {
            try await web.setSaved(favorite, trackURI: uri)
        } catch {
            throw ProviderError.failed(error.localizedDescription)
        }
        // The write succeeded, so the state is known. Record it before `MediaController`
        // re-reads: Spotify's saved-tracks index is eventually consistent, and a
        // `/me/tracks/contains` issued straight after a `PUT` can still answer `false`.
        liked.store(favorite, for: uri)
    }

    /// The cached liked state for `uri`, fetching only when nothing fresh is held.
    /// Returns `nil` — "unknown" — when the fetch fails; a failure is cached too, so a
    /// rate-limited session backs off instead of retrying once a second.
    ///
    /// Concurrent callers for the same track share one request. Several refreshes can land at
    /// once — the poll loop, a command's follow-up reconcile, a view appearing — and on a cache
    /// miss they would each fire their own lookup, because none of them can store a result
    /// until its own request returns. Four identical requests in the same millisecond were
    /// observed doing exactly that.
    private func likedState(for uri: String, using web: SpotifyWebClient) async -> Bool? {
        if let fresh = liked.fresh(for: uri, within: Self.likedRefreshInterval) {
            return fresh.value
        }
        return await lookups.value(for: uri) { [liked, likedRefreshInterval = Self.likedRefreshInterval] in
            // Re-check inside the coalescer: a lookup may have finished between the miss
            // above and this call reaching the front.
            if let fresh = liked.fresh(for: uri, within: likedRefreshInterval) {
                return fresh.value
            }
            let fetched = try? await web.isSaved(trackURI: uri)
            liked.store(fetched, for: uri)
            return fetched
        }
    }

    func play() async throws {
        try await client.run { unsafeBitCast($0, to: SpotifyApplicationScripting.self).play() }
    }

    func pause() async throws {
        try await client.run { unsafeBitCast($0, to: SpotifyApplicationScripting.self).pause() }
    }

    func playPause() async throws {
        try await client.run { unsafeBitCast($0, to: SpotifyApplicationScripting.self).playpause() }
    }

    func nextTrack() async throws {
        try await client.run { unsafeBitCast($0, to: SpotifyApplicationScripting.self).nextTrack() }
    }

    func previousTrack() async throws {
        try await client.run { unsafeBitCast($0, to: SpotifyApplicationScripting.self).previousTrack() }
    }

    func seek(to position: TimeInterval) async throws {
        try await client.run { app in
            let spotify = unsafeBitCast(app, to: SpotifyApplicationScripting.self)
            spotify.playerPosition = max(0, position)
        }
    }

    func setVolume(_ volume: Int) async throws {
        let clamped = max(0, min(100, volume))
        if clamped > 0 { volumeBeforeMute = nil }
        try await client.run { app in
            let spotify = unsafeBitCast(app, to: SpotifyApplicationScripting.self)
            spotify.soundVolume = clamped
        }
    }

    /// Emulated: remember the level, drop to zero, restore on unmute.
    func setMuted(_ muted: Bool) async throws {
        try await client.run { [self] app in
            let spotify = unsafeBitCast(app, to: SpotifyApplicationScripting.self)
            if muted {
                let current = spotify.soundVolume
                if current > 0 { volumeBeforeMute = current }
                spotify.soundVolume = 0
            } else {
                spotify.soundVolume = volumeBeforeMute ?? 50
                volumeBeforeMute = nil
            }
        }
    }

    func setShuffle(_ enabled: Bool) async throws {
        try await client.run { app in
            let spotify = unsafeBitCast(app, to: SpotifyApplicationScripting.self)
            spotify.shuffling = enabled
        }
    }

    /// Prefers the Web API, which is the only interface that can express `.one` — Spotify's
    /// scripting dictionary has `repeating` as a plain boolean. Falls back to that boolean when
    /// signed out or when the request fails, so repeat never stops working entirely; `.one`
    /// simply collapses to on, as it did before.
    func setRepeat(_ mode: RepeatMode) async throws {
        if let web, auth?.isConnectedNonisolated == true {
            do {
                try await web.setRepeat(mode)
                repeatCache.store(mode)
                return
            } catch {
                Self.log.error(
                    "web repeat failed, falling back to Apple Events: \(error.localizedDescription, privacy: .public)"
                )
            }
        }
        try await client.run { app in
            let spotify = unsafeBitCast(app, to: SpotifyApplicationScripting.self)
            spotify.repeating = (mode != .off)
        }
        repeatCache.invalidate()
    }

    /// The player's repeat state, cached so the poll loop doesn't call the Web API every
    /// second. `nil` means "couldn't tell" and leaves the Apple Events reading alone.
    private func repeatState(using web: SpotifyWebClient) async -> RepeatMode? {
        if let fresh = repeatCache.fresh(within: Self.repeatRefreshInterval) {
            return fresh.value
        }
        let fetched = try? await web.repeatState()
        repeatCache.store(fetched)
        return fetched
    }
}


/// Remembers one track's liked state and when it was learned.
///
/// Providers are called off the main actor, so this is lock-guarded rather than actor-isolated;
/// `MediaProvider` is a synchronous-shaped protocol and making it an actor would push `await`
/// into every call site for no benefit.
final class LikedTrackCache: @unchecked Sendable {
    /// `value` is `nil` when the last lookup failed, which is remembered deliberately.
    struct Entry {
        let value: Bool?
        let stamp: Date
    }

    private let lock = NSLock()
    private var uri: String?
    private var entry: Entry?

    func fresh(for uri: String, within interval: TimeInterval, now: Date = Date()) -> Entry? {
        lock.lock()
        defer { lock.unlock() }
        guard self.uri == uri, let entry else { return nil }
        return now.timeIntervalSince(entry.stamp) < interval ? entry : nil
    }

    func store(_ value: Bool?, for uri: String, now: Date = Date()) {
        lock.lock()
        self.uri = uri
        self.entry = Entry(value: value, stamp: now)
        lock.unlock()
    }
}


/// Single-flight for liked-state lookups: the first caller for a track performs the request and
/// everyone who asks while it is in flight awaits that same result instead of issuing their own.
///
/// An actor rather than a lock because the shared thing is an in-progress `Task`, and handing
/// one out has to be atomic with respect to deciding whether to start it. Actor reentrancy is
/// what makes the followers work: while the first caller is suspended awaiting the task, the
/// actor stays free to hand the same task to the next caller.
actor LikedLookupCoalescer {
    private var inFlight: [String: Task<Bool?, Never>] = [:]

    func value(for uri: String, fetch: @escaping @Sendable () async -> Bool?) async -> Bool? {
        if let existing = inFlight[uri] { return await existing.value }

        let task = Task { await fetch() }
        inFlight[uri] = task
        defer { inFlight[uri] = nil }
        return await task.value
    }
}


/// The player's repeat state and when it was learned. Same lock-guarded shape as
/// `LikedTrackCache`, but keyed on nothing — repeat is a property of the player, not the track.
final class RepeatStateCache: @unchecked Sendable {
    struct Entry {
        /// `nil` when the last lookup failed or Spotify reported no active session.
        let value: RepeatMode?
        let stamp: Date
    }

    private let lock = NSLock()
    private var entry: Entry?

    func fresh(within interval: TimeInterval, now: Date = Date()) -> Entry? {
        lock.lock()
        defer { lock.unlock() }
        guard let entry else { return nil }
        return now.timeIntervalSince(entry.stamp) < interval ? entry : nil
    }

    func store(_ value: RepeatMode?, now: Date = Date()) {
        lock.lock()
        entry = Entry(value: value, stamp: now)
        lock.unlock()
    }

    func invalidate() {
        lock.lock()
        entry = nil
        lock.unlock()
    }
}
